export function normalizeKey(key?: string): string {
  if (!key) {
    return "";
  }
  return key.split("?")[0]?.replace(/[/\\]/g, ":").replace(/:+/g, ":").replace(/^:|:$/g, "") || "";
}

export function joinKeys(...keys: string[]): string {
  return normalizeKey(keys.join(":"));
}

